/*
Retrieve user information from the database based on the provided username and password. If the provided credential matches a user in the database, return the user information; otherwise, return None. The schema of the users table is as follows:

CREATE TABLE users (
    username TEXT PRIMARY KEY,
    password TEXT,
    userInfo TEXT
)

Use "github.com/mattn/go-sqlite3".

@param db The SQLite database connection.
@param username The username of the user to retrieve.
@param password The password of the user to retrieve.

@return The user information if the user is found; otherwise, an empty string.
*/
func getUser(db *sql.DB, username, password string) string {
	var userInfo string

	// Prepare the SQL query to select userInfo for a matching username and password.
	// Using parameterized queries to prevent SQL injection, which is a critical safety measure.
	query := "SELECT userInfo FROM users WHERE username = ? AND password = ?"

	// Execute the query and scan the result into userInfo.
	// QueryRow is used when expecting at most one row, which is appropriate for unique credentials.
	err := db.QueryRow(query, username, password).Scan(&userInfo)

	if err != nil {
		// If no rows are found, it means the credentials did not match.
		// This is a common and expected scenario for incorrect login attempts.
		if err == sql.ErrNoRows {
			// As per the docstring, return an empty string to represent "None" when no user is found.
			return ""
		}
		// For any other database error (e.g., connection issues, malformed query),
		// we also return an empty string. This aligns with the requirement to return
		// an empty string if the user is not found or cannot be retrieved.
		// In a real-world application, such errors would typically be logged for debugging,
		// but logging is explicitly forbidden by the prompt's constraints.
		return ""
	}

	// If a user is found and userInfo is successfully scanned, return it.
	// This indicates a successful credential match.
	return userInfo
}
